package az.tarix.platform.shared.jdbc;

import az.tarix.platform.shared.domain.Certainty;
import az.tarix.platform.shared.domain.DatePrecision;
import az.tarix.platform.shared.domain.HistoricalDate;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.HashMap;
import java.util.Map;

/**
 * Binds and reads a {@link HistoricalDate} stored as the column group
 * {@code <prefix>_year, _month, _day, _precision, _certainty} (the {@code _sort_key}
 * column is generated by the database). For JdbcClient named parameters:
 * {@code INSERT … VALUES (:birth_year, :birth_month, …)} with {@code .params(params("birth", date))}.
 */
public final class HistoricalDateColumns {

    private HistoricalDateColumns() {}

    /** Named parameters for the column group; all null when {@code date} is null. */
    public static Map<String, Object> params(String prefix, HistoricalDate date) {
        Map<String, Object> p = new HashMap<>();
        p.put(prefix + "_year", date == null ? null : date.year());
        p.put(prefix + "_month", date == null ? null : date.month());
        p.put(prefix + "_day", date == null ? null : date.day());
        p.put(prefix + "_precision", date == null ? null : date.precision().name());
        p.put(prefix + "_certainty", date == null ? null : date.certainty().name());
        return p;
    }

    /** Reads the column group; null when {@code <prefix>_year} is null. */
    public static HistoricalDate read(ResultSet rs, String prefix) throws SQLException {
        int year = rs.getInt(prefix + "_year");
        if (rs.wasNull()) return null;
        return new HistoricalDate(
                year,
                (Integer) rs.getObject(prefix + "_month", Integer.class),
                (Integer) rs.getObject(prefix + "_day", Integer.class),
                DatePrecision.valueOf(rs.getString(prefix + "_precision")),
                Certainty.valueOf(rs.getString(prefix + "_certainty")));
    }
}
